impl Companion {
    pub(in crate::ui) fn home_section_heading(&self, icon: UiIcon, title: impl Into<String>) -> El {
        self.hstack(S2, vec![self.section_icon_badge(icon, 15., 26.), self.heading(title)])
    }

    pub(in crate::ui) fn home_actions(&self) -> Vec<El> {
        let mirror_btn = if self.mirror.is_some() {
            self.button(
                "home-hdr-stop-mirror",
                "结束投屏",
                Action::StopMirror,
                Btn::Danger,
            )
        } else {
            self.button_icon(
                "home-hdr-start-mirror",
                "手机投屏",
                UiIcon::Phone,
                Action::Mirror,
                Btn::Secondary,
            )
        };

        vec![mirror_btn]
    }

    pub(in crate::ui) fn render_home_workbench_banner(
        &self,
        probe_prefix: &str,
        title: String,
        date_tag: String,
        description: &str,
        actions: Vec<El>,
    ) -> El {
        let p = self.p();
        let title = home_geometry_probe(
            format!("{probe_prefix}-title"),
            self.wrap(vec![
                self.icon_badge(UiIcon::Grid, 15., p.accent, p.accent_soft, 28.),
                self.heading(title),
                self.pill_badge(date_tag, p.accent, p.accent_soft),
            ]),
        );
        let actions = home_geometry_probe(format!("{probe_prefix}-actions"), self.wrap(actions));
        home_geometry_probe(
            format!("{probe_prefix}-header"),
            Container::new(self.vstack(
                6.,
                vec![title, self.text(description, MICRO, p.text2), actions],
            ))
            .with_horizontal_padding(S3)
            .with_vertical_padding(6.)
            .with_background_color(p.card)
            .with_border(Border::all(1.).with_border_color(p.border))
            .with_corner_radius(CornerRadius::with_all(Radius::Pixels(R_PANEL)))
            .finish(),
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub(in crate::ui) fn render_single_home_module(
        &self,
        mod_id: HomeModuleId,
        height: HomeModuleHeight,
        report: &stepx_companion::home_hub::HomeHubReport,
        snapshot: &PushSnapshot,
        express_parcels: &[stepx_companion::device::ExpressParcelInfo],
        weekly_opt: Option<&stepx_companion::home_hub::WeeklyOverviewReport>,
        metrics_ref: &stepx_companion::device::DeviceMetrics,
    ) -> Option<El> {
        #[cfg(feature = "ui-capture")]
        let build_start = std::time::Instant::now();
        let raw_el: Option<El> = match mod_id {
            HomeModuleId::ProductivityHub => {
                let mut sections = Vec::new();
                if let Some(health) = self.render_productivity_health() { sections.push(health); }
                if let Some(preservation) = self.render_productivity_preservation() { sections.push(preservation); }
                sections.push(self.render_productivity_hub());
                Some(self.home_surface_stack(S2, sections))
            }
            HomeModuleId::LiveCountdown => self
                .render_home_live_countdown_banner(snapshot)
                .or_else(|| {
                    let eff_h = self.resolve_effective_height(HomeModuleId::LiveCountdown, height);
                    if !self.home_module_edit_mode
                        && self.home_pending_move.is_none()
                        && !self.home_drag_active()
                        && eff_h != HomeModuleHeight::Tall
                    {
                        return None;
                    }
                    let p = self.p();
                    let width = self.home_module_content_width(HomeModuleId::LiveCountdown);
                    let profile = self.compute_home_module_value_profile(
                        HomeModuleId::LiveCountdown,
                        width,
                        height,
                    );
                    let mut chips = vec![self.chip(
                        "home-countdown-edit-start-pomo",
                        "开启25分钟专注",
                        Some(UiIcon::Clock),
                        vec![Action::BackScreen(BackScreenAction::StartPomodoro(25))],
                        false,
                        false,
                    )];
                    if matches!(width, HomeModuleWidth::TwoThirds | HomeModuleWidth::Full)
                        || eff_h == HomeModuleHeight::Tall
                    {
                        chips.push(self.chip(
                            "home-countdown-idle-start-15",
                            "15分钟冲刺",
                            Some(UiIcon::Clock),
                            vec![Action::BackScreen(BackScreenAction::StartPomodoro(15))],
                            false,
                            false,
                        ));
                        chips.push(self.chip(
                            "home-countdown-idle-start-45",
                            "45分钟深工",
                            Some(UiIcon::Clock),
                            vec![Action::BackScreen(BackScreenAction::StartPomodoro(45))],
                            false,
                            false,
                        ));
                        chips.push(self.chip(
                            "home-countdown-idle-start-5",
                            "+5m 小憩",
                            Some(UiIcon::Clock),
                            vec![Action::BackScreen(BackScreenAction::StartPomodoro(5))],
                            false,
                            false,
                        ));
                    }
                    let desc = Self::truncate_chars("专注倒计时", profile.char_budget);
                    Some(self.home_frame(HomeModuleId::LiveCountdown, vec![row_between_expanded(
                        self.hstack(
                            S2,
                            vec![
                                self.ui_icon_box(
                                    UiIcon::Clock,
                                    24.,
                                    soft_tint(p.indigo, p.dark),
                                    p.indigo,
                                    None,
                                ),
                                self.line_w(desc, CAPTION, p.text2, Weight::Medium),
                            ],
                        ),
                        self.wrap(chips),
                        S2,
                    )]))
                }),
            HomeModuleId::CalendarPanorama => Some(self.render_home_calendar_hub_and_panorama()),
            HomeModuleId::WeeklyAndAi => {
                let wk = weekly_opt?;
                Some(self.render_home_weekly_and_ai_row(report, wk))
            }
            HomeModuleId::WorkModule => Some(self.render_home_calendar_and_work_column(report)),
            HomeModuleId::LifeModule => {
                Some(self.render_home_life_and_express_column(snapshot, express_parcels, report))
            }
            HomeModuleId::IssuesAndReplyModule => {
                Some(self.render_home_issues_and_reply_column(snapshot, report))
            }
            HomeModuleId::PulseAndKpi => Some(self.render_home_pulse_telemetry_card(report)),
            HomeModuleId::AlarmsAndControl => {
                Some(self.render_home_alarms_and_control_column(report))
            }
            HomeModuleId::BackScreenAndHabits => {
                let width = self.home_module_content_width(HomeModuleId::BackScreenAndHabits);
                let eff_h =
                    self.resolve_effective_height(HomeModuleId::BackScreenAndHabits, height);
                let studio_card =
                    self.render_home_device_and_backscreen_studio_card(report, metrics_ref);
                if eff_h == HomeModuleHeight::Compact {
                    Some(studio_card)
                } else {
                    let habit_card = self.render_home_habit_donut_card();
                    if matches!(
                        width,
                        HomeModuleWidth::OneHalf
                            | HomeModuleWidth::TwoThirds
                            | HomeModuleWidth::Full
                    ) {
                        Some(self.home_aligned_columns(
                            520.,
                            S2,
                            S2,
                            vec![(1.08, studio_card), (1.0, habit_card)],
                        ))
                    } else {
                        Some(self.home_surface_stack(S2, vec![studio_card, habit_card]))
                    }
                }
            }
            HomeModuleId::ToolsSummaryDock => Some(self.render_home_tools_summary_panel()),
            HomeModuleId::ContinuityWorkspace => Some(self.render_home_continuity()),
            HomeModuleId::ContextLedgerHub => Some(self.render_context_panel()),
            HomeModuleId::QuickStartRequest => Some(self.render_home_new_request()),
            HomeModuleId::WeatherModule if self.resolve_effective_height(mod_id, height) == HomeModuleHeight::Compact => {
                let p = self.p();
                let weather = &self.weather_snapshot;
                if !weather.from_live_api && !self.demo_mode {
                    return Some(self.home_frame(HomeModuleId::WeatherModule, vec![
                        row_between_expanded(self.home_section_heading(UiIcon::Sun, "天气"),
                            self.button_icon("home-weather-refresh", "刷新", UiIcon::Refresh,
                                Action::WeatherRefresh, Btn::Ghost), S2),
                        self.text("刷新后查看当前天气与出行提示", CAPTION, p.text2),
                    ]));
                }
                Some(self.home_frame(HomeModuleId::WeatherModule, vec![
                    row_between_expanded(
                        self.home_section_heading(UiIcon::Sun, "天气"),
                        self.hstack(S1, vec![
                            self.button("home-weather-open-tool", "详情", Action::OpenTool(Some(ToolPage::Weather)), Btn::Ghost),
                            self.icon_action("home-weather-refresh", "刷新天气", UiIcon::Refresh,
                                vec![Action::WeatherRefresh], false),
                        ]), S2,
                    ),
                    self.wrap(vec![self.text_w(format!("{}°C", weather.temp_c), 24., p.text, Weight::Semibold),
                        self.line(&weather.city, CAPTION, p.text2),
                        self.line(&weather.condition, CAPTION, p.text2), self.line(weather.range_label(), CAPTION, p.text2)]),
                    self.text(&weather.commute_advice, CAPTION, p.text2),
                    self.text(format!("{} · {}", weather.source_label(), weather.updated_label), MICRO, p.text3),
                ]))
            }
            HomeModuleId::WeatherModule => Some(self.render_home_weather_module_card(report)),
            HomeModuleId::RecentFiles => Some(self.render_recent_files()),
        };

        #[cfg(feature = "ui-capture")]
        HOME_BUILD_STAGES.with(|stages| {
            stages.borrow_mut().insert(mod_id.slug().into(), build_start.elapsed().as_micros() as u64);
        });
        raw_el
    }

    #[cfg(feature = "ui-capture")]
    pub(in crate::ui) fn home_build_stages(&self) -> std::collections::BTreeMap<String, u64> {
        HOME_BUILD_STAGES.with(|stages| stages.borrow().clone())
    }

    #[cfg(feature = "ui-capture")]
    pub(in crate::ui) fn home_build_count(&self) -> u64 { HOME_BUILD_COUNT.with(|c| c.get()) }

    pub(in crate::ui) fn access_last_home_page_build_us(set: Option<u64>) -> u64 {
        thread_local! {
            static LAST_US: std::cell::Cell<u64> = const { std::cell::Cell::new(0) };
        }
        LAST_US.with(|c| {
            if let Some(v) = set {
                c.set(v);
            }
            c.get()
        })
    }

    pub(in crate::ui) fn last_home_page_build_us(&self) -> u64 {
        Self::access_last_home_page_build_us(None)
    }

    pub(in crate::ui) fn home_page(&self) -> El {
        let t0 = std::time::Instant::now();
        #[cfg(feature = "ui-capture")]
        {
            HOME_BUILD_COUNT.with(|c| c.set(c.get() + 1));
            HOME_BUILD_STAGES.with(|stages| stages.borrow_mut().clear());
        }
        let el = self.home_page_inner();
        Self::access_last_home_page_build_us(Some(t0.elapsed().as_micros() as u64));
        el
    }

    pub(in crate::ui) fn home_page_inner(&self) -> El {
        if self.productivity_preview_is_open() {
            let p = self.p();
            let back_bar = Container::new(row_between_expanded(
                self.hstack(
                    S2,
                    vec![
                        self.button_icon(
                            "home-productivity-back-to-workbench",
                            "返回首页工作台",
                            UiIcon::ArrowLeft,
                            Action::Productivity(
                                crate::ui::productivity_state::ProductivityAction::ClosePreview,
                            ),
                            Btn::Primary,
                        ),
                        self.line_w("正在查看资料原文预览", SUBHEAD, p.text, Weight::Semibold),
                    ],
                ),
                self.button_icon(
                    "home-mod-bar-edit-toggle",
                    if self.home_module_edit_mode {
                        "完成编辑"
                    } else {
                        "调整布局"
                    },
                    if self.home_module_edit_mode {
                        UiIcon::Check
                    } else {
                        UiIcon::Layers
                    },
                    Action::HomeModule(HomeModuleAction::ToggleEditMode),
                    Btn::Secondary,
                ),
                S2,
            ))
            .with_horizontal_padding(S3)
            .with_vertical_padding(7.)
            .with_background_color(p.card)
            .with_border(Border::all(1.).with_border_color(p.accent))
            .with_corner_radius(CornerRadius::with_all(Radius::Pixels(R_PANEL)))
            .finish();
            return Align::new(
                ConstrainedBox::new(
                    self.vstack(S3, vec![back_bar, self.render_productivity_hub()]),
                )
                .with_max_width(1380.)
                .finish(),
            )
            .top_center()
            .finish();
        }
        if self.context_home_is_focused() {
            let p = self.p();
            let back_bar = Container::new(row_between_expanded(
                self.hstack(
                    S2,
                    vec![
                        self.button_icon(
                            "home-context-back-to-workbench",
                            "返回首页工作台",
                            UiIcon::ArrowLeft,
                            Action::Context(crate::ui::context_state::ContextAction::Attention),
                            Btn::Primary,
                        ),
                        self.line_w(
                            "正在查看跨端记忆详情视图",
                            SUBHEAD,
                            p.text,
                            Weight::Semibold,
                        ),
                    ],
                ),
                self.button_icon(
                    "home-mod-bar-edit-toggle",
                    if self.home_module_edit_mode {
                        "完成编辑"
                    } else {
                        "调整布局"
                    },
                    if self.home_module_edit_mode {
                        UiIcon::Check
                    } else {
                        UiIcon::Layers
                    },
                    Action::HomeModule(HomeModuleAction::ToggleEditMode),
                    Btn::Secondary,
                ),
                S2,
            ))
            .with_horizontal_padding(S3)
            .with_vertical_padding(7.)
            .with_background_color(p.card)
            .with_border(Border::all(1.).with_border_color(p.accent))
            .with_corner_radius(CornerRadius::with_all(Radius::Pixels(R_PANEL)))
            .finish();
            let mut focused_sections = vec![back_bar];
            if self.home_module_edit_mode {
                focused_sections.push(self.render_home_module_editor_studio());
            }
            focused_sections.push(self.render_context_panel());
            return Align::new(
                ConstrainedBox::new(self.vstack(S3, focused_sections))
                    .with_max_width(1380.)
                    .finish(),
            )
            .top_center()
            .finish();
        }
        let demo_push: PushSnapshot;
        let snapshot: &PushSnapshot = if self.demo_mode
            && self.push.snapshot.notifications.is_empty()
            && self.push.snapshot.threads.is_empty()
        {
            demo_push = demo_push_snapshot();
            &demo_push
        } else {
            &self.push.snapshot
        };
        let fallback_parcels;
        let express_parcels = if self.demo_mode && self.express_parcels.is_empty() {
            fallback_parcels = default_express_parcels();
            &fallback_parcels
        } else {
            &self.express_parcels
        };
        self.with_home_hub_input(
            snapshot,
            express_parcels,
            |input, today_ymd, selected_ymd| {
                let desktop_entries = self.home_desktop_date_entries();
                let report_val =
                    self.build_report_from_input(input, today_ymd, selected_ymd, &desktop_entries);
                let report = &report_val;

                let needs_weekly = self.home_modules.is_enabled(HomeModuleId::WeeklyAndAi);
                let needs_metrics = self
                    .home_modules
                    .is_enabled(HomeModuleId::BackScreenAndHabits);

                let weekly_opt = needs_weekly
                    .then(|| build_weekly_overview_report(selected_ymd, input, &desktop_entries));
                let metrics_opt = needs_metrics.then(|| self.cached_device_metrics());
                let empty_metrics = stepx_companion::device::DeviceMetrics::default();
                let metrics_ref = metrics_opt.as_ref().unwrap_or(&empty_metrics);

                {
                    let mut reg = self.home_pointer_registry.borrow_mut();
                    reg.observe_layout(self.home_modules.enabled.iter().map(|id| (*id,
                        self.home_modules.module_width(*id), self.home_modules.module_height(*id))).collect(),
                        !self.animations_disabled());
                    reg.card_rects
                        .retain(|id, _| self.home_modules.is_enabled(*id));
                    reg.drag_handle_rects
                        .retain(|id, _| self.home_modules.is_enabled(*id));
                    reg.resize_handle_rects
                        .retain(|id, _| self.home_modules.is_enabled(*id));
                    reg.reminder_rects.clear();
                }

                let p = self.p();
                let _ = p;
                let mut ordered: Vec<El> = Vec::with_capacity(self.home_modules.enabled.len() + 3);
                if self.home_module_edit_mode {
                    ordered.push(self.render_home_module_editor_studio());
                } else {
                    ordered.push(self.render_home_modular_toolbar_strip());
                }
                // Real failures remain reachable without putting engineering
                // diagnostics ahead of the user's calendar and daily work.
                let mut source_notices = Vec::new();
                if !self.home_modules.is_enabled(HomeModuleId::ProductivityHub) {
                    if self.productivity_health_status().is_some() {
                        source_notices.push(self.chip("home-source-update-status", "部分资料待更新 · 查看来源",
                            Some(UiIcon::Alert), vec![Action::Context(crate::ui::context_state::ContextAction::Coverage)], false, false));
                    }
                    if self.productivity_preservation_status().is_some() {
                        source_notices.push(self.chip("home-source-storage-status", "资料归档需检查",
                            Some(UiIcon::Folder), vec![Action::Page(Page::Expansion)], false, false));
                    }
                }
                let mut source_notice = (!source_notices.is_empty()).then(|| self.wrap(source_notices));
                if !self.home_modules.is_enabled(HomeModuleId::CalendarPanorama) {
                    if let Some(notice) = source_notice.take() { ordered.push(notice); }
                }

                let total_enabled = self.home_modules.enabled.len();
                let packed_rows = self.home_modules.pack_rows();
                let mut rank_cursor = 0usize;

                for row in packed_rows {
                    let configured_count = row.len();
                    let row_start_idx = rank_cursor;
                    let all_core_workbench =
                        !row.is_empty() && row.iter().all(|(id, _, _)| id.is_core_workbench_col());

                    let mut rendered_cols: Vec<(f32, El)> = Vec::with_capacity(row.len());
                    let mut group_ids: Vec<(usize, HomeModuleId)> = Vec::with_capacity(row.len());

                    for (mod_id, width, height) in row {
                        let rank_idx = rank_cursor;
                        rank_cursor += 1;
                        if let Some(el) = self.render_single_home_module(
                            mod_id,
                            height,
                            report,
                            snapshot,
                            express_parcels,
                            weekly_opt.as_ref(),
                            metrics_ref,
                        ) {
                            group_ids.push((rank_idx, mod_id));
                            rendered_cols.push((
                                width.flex_weight(),
                                self.wrap_module_with_edit_controls(
                                    mod_id,
                                    rank_idx,
                                    total_enabled,
                                    el,
                                ),
                            ));
                        }
                    }

                    if rendered_cols.is_empty() {
                        continue;
                    }

                    let row_el = self.home_canvas_columns(configured_count, rendered_cols);

                    if all_core_workbench {
                        // 不再渲染「今日事项 · …」说明横幅，模块卡片自带标题。
                        let _ = &group_ids;
                        ordered.push(home_geometry_probe(
                            format!("home-workbench-{row_start_idx}-card"),
                            row_el,
                        ));
                    } else {
                        ordered.push(row_el);
                    }
                    if group_ids.iter().any(|(_, id)| *id == HomeModuleId::CalendarPanorama) {
                        if let Some(notice) = source_notice.take() { ordered.push(notice); }
                    }
                }

                let mut module_sizes = std::collections::BTreeMap::new();
                for &id in &self.home_modules.enabled {
                    module_sizes.insert(
                        id,
                        (
                            self.home_modules.module_width(id),
                            self.home_modules.module_height(id),
                        ),
                    );
                }

                let aligned = Align::new(
                    ConstrainedBox::new(
                        Container::new(self.vstack(S2, ordered))
                            .with_padding_bottom(S2)
                            .finish(),
                    )
                    .with_max_width(layout_config::HOME_CONTENT_MAX_WIDTH)
                    .finish(),
                )
                .top_center()
                .finish();

                let active_op_snapshot = self.home_pointer_registry.borrow().active_op.clone();
                let floating_badge = active_op_snapshot.map(|op| {
                    let label = match op {
                        HomePointerOp::DragModule {
                            source,
                            hover_target,
                            ..
                        } => match hover_target {
                            Some(tgt) => format!(
                                "⠿ 拖动中：{} → 释放插入「{}」附近",
                                source.short_title(),
                                tgt.short_title()
                            ),
                            None => format!(
                                "⠿ 拖动中：{}（移至目标模块上释放可排序）",
                                source.short_title()
                            ),
                        },
                        HomePointerOp::ResizeModule {
                            module,
                            preview_width,
                            preview_height,
                            ..
                        } => format!(
                            "⤡ 缩放中：{} → {}宽 · {}高",
                            module.short_title(),
                            preview_width.short_label(),
                            preview_height.short_label()
                        ),
                    };
                    Container::new(self.line_w(label, CAPTION, p.accent, Weight::Semibold))
                        .with_horizontal_padding(10.)
                        .with_vertical_padding(5.)
                        .with_background_color(p.card)
                        .with_border(Border::all(1.5).with_border_color(p.accent))
                        .with_corner_radius(CornerRadius::with_all(Radius::Pixels(R_SM)))
                        .finish()
                });

                Box::new(HomeInteractiveCanvas {
                    child: aligned,
                    editing: self.home_module_edit_mode || self.home_pending_move.is_some(),
                    floating_badge,
                    registry: self.home_pointer_registry.clone(),
                    module_sizes,
                    accent: p.accent,
                    surface: p.card,
                    size: None,
                    origin: None,
                })
            },
        )
    }

    /// Recent actual conversations, with duplicate unsent drafts collapsed only on Home.
    pub(in crate::ui) fn home_recent_tasks(&self) -> Vec<&stepx_companion::amoo_workspace::Task> {
        self.home_recent_tasks_limited(2)
    }

    pub(in crate::ui) fn home_recent_tasks_limited(
        &self,
        max_items: usize,
    ) -> Vec<&stepx_companion::amoo_workspace::Task> {
        use stepx_companion::amoo_workspace::Phase;
        let mut tasks: Vec<_> = self
            .workspace
            .journal
            .tasks
            .iter()
            .filter(|task| self.workspace_visible(task))
            .filter(|task| {
                !stepx_companion::home_hub::any_synthetic_e2e_probe(&[&task.title, &task.draft])
            })
            .filter(|task| {
                !task.turns.is_empty()
                    || !task.draft.trim().is_empty()
                    || !task.attachments.is_empty()
                    || !task.outputs.is_empty()
                    || !task.steps.is_empty()
            })
            .collect();
        let recent_since = Local::now().timestamp().saturating_sub(7 * 86_400);
        tasks.sort_by_key(|task| {
            let running = self
                .workspace
                .running
                .as_ref()
                .is_some_and(|run| run.task == task.id);
            let recent = task.updated >= recent_since;
            let priority = match (running, recent, task.steps.last().map(|s| s.phase)) {
                (true, _, _) => 0,
                (_, true, Some(Phase::Failed | Phase::Unconfirmed)) => 1,
                _ => 2,
            };
            (priority, std::cmp::Reverse(task.updated))
        });
        let mut drafts = std::collections::HashSet::new();
        tasks.retain(|task| {
            if task.turns.is_empty() && task.outputs.is_empty() && task.steps.is_empty() {
                drafts.insert((task.title.as_str(), task.draft.as_str(), &task.attachments))
            } else {
                true
            }
        });
        tasks.truncate(max_items.max(1));
        tasks
    }

    pub(in crate::ui) fn render_home_tools_summary_panel(&self) -> El {
        let p = self.p();
        let mod_w = self.home_module_content_width(HomeModuleId::ToolsSummaryDock);
        let mod_h = self
            .home_modules
            .module_height(HomeModuleId::ToolsSummaryDock);
        let eff_h = self.resolve_effective_height(HomeModuleId::ToolsSummaryDock, mod_h);
        let profile =
            self.compute_home_module_value_profile(HomeModuleId::ToolsSummaryDock, mod_w, mod_h);
        let online = self.demo_mode || self.selected.is_some();
        let _ = online;
        let title_row = self.home_section_heading(UiIcon::Apps, "快捷工具");
        // Local disclosure is available in normal use and never changes which
        // homepage modules the user chose to show.
        let header = row_between_expanded(
                title_row,
                home_geometry_probe("home-toggle-tools", self.button_icon(
                    "home-toggle-tools",
                    if self.home_tools_expanded {
                        "收起"
                    } else {
                        "展开"
                    },
                    if self.home_tools_expanded {
                        UiIcon::Layers
                    } else {
                        UiIcon::Grid
                    },
                    Action::HomeToggleTools,
                    Btn::Ghost,
                )),
                S2,
            );

        let suite = &self.back_screen.stepos_suite;
        let is_genuine_thread = |t: &stepx_companion::push::ImThread| -> bool {
            !t.title.trim_start().starts_with('{')
                && !stepx_companion::push::is_excluded_im_package(&t.package_name)
                && !stepx_companion::home_hub::any_synthetic_e2e_probe(&[
                    &t.app_name,
                    &t.title,
                    &t.last_message,
                ])
        };
        let unread_threads = self
            .push
            .snapshot
            .threads
            .iter()
            .filter(|t| t.unread_count > 0 && is_genuine_thread(t))
            .count();
        let now_ms = Local::now().timestamp_millis().max(0) as u64;
        let unread_sms = self
            .sms
            .iter()
            .filter(|m| {
                m.kind == 1
                    && !m.read
                    && now_ms.saturating_sub(m.date_ms.max(0) as u64) <= 12 * 3600 * 1000
                    && !stepx_companion::home_hub::any_synthetic_e2e_probe(&[&m.address, &m.body])
            })
            .count();
        let unread_total: usize = self
            .push
            .snapshot
            .threads
            .iter()
            .filter(|t| is_genuine_thread(t))
            .map(|t| t.unread_count)
            .sum::<usize>()
            + unread_sms;
        let now = Local::now();
        let now_ms = now.timestamp_millis();
        let today_unexpired_alarms = suite
            .alarms
            .iter()
            .filter(|a| a.is_today_valid_unexpired_at(now_ms, &self.reminder_governance))
            .count();
        let enabled_alarms = suite
            .alarms
            .iter()
            .filter(|a| a.is_valid_future_or_today_unexpired_at(now_ms, &self.reminder_governance))
            .count();
        let cal_count = suite
            .calendar_events
            .iter()
            .filter(|e| {
                e.is_today_valid_unexpired_at(
                    now_ms,
                    &self.back_screen.completed_calendar_events,
                    &self.reminder_governance,
                )
            })
            .count();
        let pomo_active = self.back_screen.pomodoro_active;
        let screen_mins = suite.wellbeing.screen_time_minutes;
        let screen_ratio = (screen_mins as f32 / 360.0).clamp(0.0, 1.0);

        let tile = |id: &str,
                    icon: UiIcon,
                    fg: ColorU,
                    bg: ColorU,
                    title: &str,
                    value: String,
                    sub: String,
                    badge: (&str, ColorU, ColorU),
                    bar: Option<(f32, ColorU)>,
                    action: Action|
         -> El {
            let state = self.mouse_state(id);
            let title_str = title.to_string();
            // 只显示标题 + 一个主数值；状态徽标、说明行与进度条不再展示。
            let _ = (&sub, &badge, &bar);
            let el = Hoverable::new(state, move |mouse| {
                let t = self.hover_t(&mouse);
                let body = vec![
                    self.hstack(
                        S2,
                        vec![
                            self.icon_badge(icon, 14., fg, bg, 28.),
                            self.text_w(&title_str, CAPTION, p.text2, Weight::Medium),
                        ],
                    ),
                    self.text_w(&value, SUBHEAD, p.text, Weight::Semibold),
                ];
                self.card_box(
                    self.vstack(4., body),
                    lerp_color(p.card, p.hover, t),
                    lerp_color(p.border, fg, t * 0.6),
                    R_SM,
                    12.,
                    8.,
                )
            })
            .with_cursor(Cursor::PointingHand)
            .on_click(move |ctx, _, _| ctx.dispatch_typed_action(action.clone()))
            .finish();
            home_geometry_probe(id.to_string(), el)
        };

        let suite_known =
            self.demo_mode || (suite.checked && self.back_screen.stepos_suite_synced_at.is_some());
        let message_known = self.demo_mode || (self.push.loaded && self.sms_loaded);

        let msg_tile = tile(
            "home-summary-tile-msg",
            UiIcon::Chat,
            p.accent,
            p.accent_soft,
            "消息",
            if unread_total > 0 {
                format!("{unread_total} 条未读")
            } else if message_known {
                "消息已读完".into()
            } else {
                "等待同步".into()
            },
            if message_known || unread_threads > 0 {
                format!("{unread_threads} 个活跃会话 · 查看消息与回复入口")
            } else {
                "同步后显示未读会话 · 查看消息与回复入口".into()
            },
            (
                if unread_total > 0 {
                    "待处理"
                } else if message_known {
                    "清爽"
                } else {
                    "待确认"
                },
                if unread_total > 0 {
                    p.accent
                } else if message_known {
                    p.success
                } else {
                    p.text2
                },
                if unread_total > 0 {
                    p.accent_soft
                } else if message_known {
                    p.success_soft
                } else {
                    p.card2
                },
            ),
            Some((
                if unread_total > 0 {
                    (unread_total as f32 / 12.0).clamp(0.15, 1.0)
                } else if message_known {
                    1.0
                } else {
                    0.12
                },
                if unread_total > 0 {
                    p.accent
                } else if message_known {
                    p.success
                } else {
                    p.text3
                },
            )),
            Action::Page(Page::Sms),
        );

        let active_countdowns = self.active_home_countdown_timers(&self.push.snapshot);
        let first_countdown = active_countdowns.first();

        let schedule_tile = tile(
            "home-summary-tile-schedule",
            if first_countdown.is_some() {
                UiIcon::Clock
            } else {
                UiIcon::Calendar
            },
            if first_countdown.is_some() {
                p.warning
            } else {
                p.indigo
            },
            if first_countdown.is_some() {
                p.warning_soft
            } else {
                p.indigo_soft
            },
            "日程",
            if let Some(cd) = first_countdown {
                format!("{} · {}", cd.title, cd.remaining_label)
            } else if suite_known {
                format!("{cal_count} 项有效日程")
            } else {
                "等待同步".into()
            },
            if first_countdown.is_some() {
                format!("{cal_count} 项有效日程 · 今日待响 {today_unexpired_alarms} 个闹钟")
            } else if suite_known {
                format!(
                    "今日待响 {today_unexpired_alarms} 个 · 有效开启 {enabled_alarms} 个闹钟 · 24h 时间轴"
                )
            } else {
                "同步后显示日程与闹钟 · 24h 时间轴".into()
            },
            (
                if first_countdown.is_some() {
                    "倒计时中"
                } else if suite_known {
                    "今日规划"
                } else {
                    "待确认"
                },
                if first_countdown.is_some() {
                    p.warning
                } else {
                    p.indigo
                },
                if first_countdown.is_some() {
                    p.warning_soft
                } else {
                    p.indigo_soft
                },
            ),
            Some((
                if let Some(cd) = first_countdown {
                    (cd.progress_pct as f32 / 100.0).clamp(0.12, 1.0)
                } else if suite_known {
                    (cal_count as f32 / 6.0).clamp(0.12, 1.0)
                } else {
                    0.12
                },
                if first_countdown.is_some() {
                    p.warning
                } else {
                    p.indigo
                },
            )),
            Action::Page(Page::Calendar),
        );

        let focus_tile = tile(
            "home-summary-tile-focus",
            UiIcon::Activity,
            p.teal,
            p.teal_soft,
            "用机",
            if pomo_active {
                "番茄钟进行中".into()
            } else if suite_known && screen_mins > 0 {
                format!("亮屏 {}m", screen_mins)
            } else {
                "25m 专注就绪".into()
            },
            if suite_known {
                format!(
                    "解锁 {} 次 · 快递与验证码即看",
                    suite.wellbeing.unlock_count
                )
            } else {
                "屏幕时长待同步 · 快递与验证码即看".into()
            },
            (
                if pomo_active {
                    "专注中"
                } else if suite_known {
                    "健康用机"
                } else {
                    "待确认"
                },
                p.teal,
                p.teal_soft,
            ),
            Some((
                if pomo_active {
                    0.72
                } else if suite_known {
                    screen_ratio.max(0.15)
                } else {
                    0.12
                },
                p.teal,
            )),
            Action::Page(Page::Alarms),
        );

        let control_tile = tile(
            "home-summary-tile-control",
            UiIcon::Matrix,
            p.warning,
            p.warning_soft,
            "背屏",
            if !suite_known {
                "状态待同步".into()
            } else if suite.controls.dnd_on {
                "勿扰已开启".into()
            } else {
                format!("亮度 {}%", suite.controls.brightness_percent)
            },
            format!(
                "379 灯珠矩阵 · {}",
                if let Some(d) = &self.selected {
                    d.model.as_str()
                } else if self.demo_mode {
                    "演示设备"
                } else {
                    "离线可预览"
                }
            ),
            (
                if !suite_known {
                    "待确认"
                } else if suite.controls.dnd_on {
                    "静音"
                } else {
                    "矩阵就绪"
                },
                p.warning,
                p.warning_soft,
            ),
            Some((
                if suite_known {
                    (suite.controls.brightness_percent as f32 / 100.0).clamp(0.1, 1.0)
                } else {
                    0.1
                },
                p.warning,
            )),
            Action::Page(Page::BackScreen),
        );

        let mut panel_children = vec![header];

        // Reminder cards are rendered by their dedicated Home modules.
        // Do not build a second, detached element tree for this summary.

        if let Some(err_msg) = suite
            .read_error
            .as_deref()
            .filter(|s| !s.trim().is_empty())
            .or_else(|| {
                self.back_screen
                    .stepos_suite_error
                    .as_deref()
                    .filter(|s| !s.trim().is_empty())
            })
        {
            panel_children.push(self.card_box(
                row_between_expanded(
                    self.hstack(
                        S2,
                        vec![
                            self.icon_badge(UiIcon::Alert, 14., p.warning, p.warning_soft, 26.),
                            self.text(
                                format!(
                                    "手机套件采集不完整（{}），已保留上次有效快照",
                                    Self::truncate_chars(err_msg, profile.char_budget)
                                ),
                                CAPTION,
                                p.warning,
                            ),
                        ],
                    ),
                    self.button_icon(
                        "home-col-suite-retry",
                        "重试采集",
                        UiIcon::Refresh,
                        Action::BackScreen(BackScreenAction::InspectStepOsSuite),
                        Btn::Secondary,
                    ),
                    S2,
                ),
                p.warning_soft,
                with_alpha_f(p.warning, 0.3),
                R_SM,
                10.,
                8.,
            ));
        }

        let summary_cols = if eff_h == HomeModuleHeight::Compact {
            match mod_w {
                HomeModuleWidth::OneThird | HomeModuleWidth::OneHalf => 2,
                HomeModuleWidth::TwoThirds | HomeModuleWidth::Full => 4,
            }
        } else {
            profile.columns
        };
        panel_children.push(self.grid_cols(
            vec![msg_tile, schedule_tile, focus_tile, control_tile],
            summary_cols,
            S2,
        ));

        if self.home_tools_expanded {
            let mut quick_actions = vec![
                (
                    "home-dock-quick-photo",
                    "手机图库",
                    "查看照片与导入图片",
                    UiIcon::Camera,
                    p.blue,
                    Action::Page(Page::Gallery),
                ),
                (
                    "home-dock-quick-voice",
                    "Amoo 对话",
                    "继续讨论与整理资料",
                    UiIcon::Chat,
                    p.indigo,
                    Action::Page(Page::Amoo),
                ),
                (
                    "home-dock-quick-screen",
                    "投屏与录屏",
                    "打开手机画面工具",
                    UiIcon::Smartphone,
                    p.teal,
                    Action::OpenTool(Some(ToolPage::Screen)),
                ),
                (
                    "home-dock-quick-backup",
                    "文件与扩容",
                    "查看文件与管理存储",
                    UiIcon::Storage,
                    p.warning,
                    Action::Page(Page::Expansion),
                ),
            ];
            if eff_h == HomeModuleHeight::Tall {
                quick_actions.extend([
                    (
                        "home-dock-quick-files",
                        "文件互传",
                        "手机与电脑互发文件",
                        UiIcon::FolderOpen,
                        p.accent,
                        Action::Page(Page::Files),
                    ),
                    (
                        "home-dock-quick-sms",
                        "消息",
                        "聊天、短信与验证码",
                        UiIcon::Chat,
                        p.blue,
                        Action::Page(Page::Sms),
                    ),
                    (
                        "home-dock-quick-calls",
                        "电话",
                        "近期来电、通讯录与拨号",
                        UiIcon::Phone,
                        p.teal,
                        Action::Page(Page::Phone),
                    ),
                    (
                        "home-dock-quick-connect",
                        "连接诊断",
                        "无线与USB通道状态",
                        UiIcon::Link,
                        p.indigo,
                        Action::Page(Page::Connect),
                    ),
                ]);
            }
            let quick_tiles: Vec<El> = quick_actions
                .into_iter()
                .map(|(qid, qtitle, qsub, qicon, qtint, qact)| {
                    let qstate = self.mouse_state(qid);
                    let qel = Hoverable::new(qstate, move |mouse| {
                        let t = self.hover_t(&mouse);
                        self.card_box(
                            row_between_expanded(
                                self.hstack(
                                    S2,
                                    vec![
                                        self.icon_badge(
                                            qicon,
                                            14.,
                                            qtint,
                                            soft_tint(qtint, p.dark),
                                            26.,
                                        ),
                                        self.vstack(
                                            1.,
                                            vec![
                                                self.line_w(
                                                    qtitle,
                                                    CAPTION,
                                                    p.text,
                                                    Weight::Semibold,
                                                ),
                                                self.line(qsub, 10., p.text2),
                                            ],
                                        ),
                                    ],
                                ),
                                self.content_icon(UiIcon::ArrowUpRight, 13., qtint),
                                S1,
                            ),
                            lerp_color(p.surface, p.hover, t),
                            lerp_color(p.border, qtint, t * 0.55),
                            R_SM,
                            10.,
                            8.,
                        )
                    })
                    .with_cursor(Cursor::PointingHand)
                    .on_click(move |ctx, _, _| ctx.dispatch_typed_action(qact.clone()))
                    .finish();
                    home_geometry_probe(qid.to_string(), qel)
                })
                .collect();
            panel_children.push(self.grid_cols(quick_tiles, profile.columns, S2));
        }

        self.home_frame(HomeModuleId::ToolsSummaryDock, panel_children)
    }

    pub(in crate::ui) fn render_home_new_request(&self) -> El {
        let p = self.p();
        let width = self.home_module_content_width(HomeModuleId::QuickStartRequest);
        let height = self
            .home_modules
            .module_height(HomeModuleId::QuickStartRequest);
        let eff_h = self.resolve_effective_height(HomeModuleId::QuickStartRequest, height);
        let profile =
            self.compute_home_module_value_profile(HomeModuleId::QuickStartRequest, width, height);

        let header = self.home_section_heading(UiIcon::Send, "快速发起");

        // The month calendar has its own navigation and agenda; the task
        // composer belongs here and must never target a hidden calendar input.
        let composer = row_between_expanded(
                self.input(
                    F_HOME_COMMAND,
                    "说说你想完成什么，例如：写一份活动方案…",
                    None,
                ),
                self.button_icon(
                    "home-omnibox-submit",
                    "开始",
                    UiIcon::Send,
                    Action::HomeSubmitCommand,
                    Btn::Primary,
                ),
                S2,
            );

        // Choosing a template fills the draft. It must visibly select the
        // matching scene without sending or replacing the user's edits later.
        let templates = [
            ("plan", "起草方案", UiIcon::File, "写一份活动方案并整理执行清单"),
            ("summary", "今日进展", UiIcon::Activity, "总结今天的进展与下一步待办"),
            ("reply", "未读消息", UiIcon::Chat, "梳理重要未读消息并给出回复建议"),
            ("weekly", "周报纪要", UiIcon::Layers, "汇总本周关键成果并生成结构化周报"),
            ("express", "快递提醒", UiIcon::Package, "查看近期快递取件码并同步背屏提醒"),
            ("voice", "会议文字", UiIcon::File, "请根据我接下来提供的会议文字，提取已确认的结论、待办、负责人及待确认事项"),
            ("archive", "文件归档", UiIcon::FolderOpen, "归档手机回传成果并生成交付清单"),
        ];
        let draft = self.fields[F_HOME_COMMAND].text.trim();
        let exact_template = templates.iter().find(|(_, _, _, prompt)| *prompt == draft);
        let appended_template = templates.iter().find(|(_, _, _, prompt)|
            draft.ends_with(&format!("\n\n{prompt}")));
        let selected = exact_template.or(appended_template);
        let choices: Vec<El> = templates.iter().take(profile.max_items).map(|(id, label, icon, prompt)| {
            self.chip(format!("home-preset-{id}"), *label, Some(*icon),
                if draft.is_empty() || exact_template.is_some() {
                    vec![Action::HomeFillDraft((*prompt).into())]
                } else {
                    // Change only an appended preset; keep the user's wording and
                    // make repeated clicks idempotent instead of duplicating prompts.
                    let base = appended_template.and_then(|(_, _, _, previous)|
                        draft.strip_suffix(&format!("\n\n{previous}"))).unwrap_or(draft);
                    vec![Action::HomeFillDraft(format!("{base}\n\n{prompt}"))]
                },
                selected.is_some_and(|(selected_id, _, _, _)| selected_id == id), false)
        }).collect();
        let presets = self.bounded_wrap(choices);
        let feedback = match selected {
            Some((_, label, _, _)) if appended_template.is_some() => format!("已选「{label}」，保留原草稿；点开始执行"),
            Some((_, label, _, _)) => format!("已选「{label}」，可修改内容后点开始"),
            None if !draft.is_empty() => "已保留草稿；选择场景可追加要求，再点开始".into(),
            None => "选一个场景填入草稿，或直接输入事项".into(),
        };
        let footer = self.vstack(S2, vec![self.divider(), self.bounded_wrap(vec![
            self.button_icon("home-new-gui", if draft.is_empty() { "操作手机" } else { "手机执行" }, UiIcon::Smartphone,
                Action::HomeRunGuiCommand, Btn::Ghost),
            self.button_icon("home-new-work", if draft.is_empty() { "文档工作台" } else { "生成文档" }, UiIcon::File,
                Action::HomeRunWorkCommand, Btn::Ghost),
            self.button_icon("home-preset-review", "日终复盘", UiIcon::Activity,
                Action::Context(crate::ui::context_state::ContextAction::Period(
                    stepx_companion::context_ledger::Period::Day)), Btn::Ghost),
        ])]);

        let mut sections = vec![header];
        let preset_section = self.vstack(S2, vec![
            self.text(feedback, CAPTION, if selected.is_some() { p.accent } else { p.text2 }),
            presets,
        ]);
        if profile.columns >= 2 && eff_h != HomeModuleHeight::Compact {
            sections.push(self.responsive_columns(
                620., S3, S2, CrossAxisAlignment::Start,
                vec![(1.15, composer), (1., preset_section)],
            ));
        } else {
            sections.push(composer);
            sections.push(preset_section);
        }
        if let Some(result) = self.agent_result(true) {
            sections.push(result);
        }
        self.home_frame_with_footer(HomeModuleId::QuickStartRequest, sections, Some(footer))
    }

    pub(in crate::ui) fn render_home_continuity(&self) -> El {
        use stepx_companion::amoo_workspace::Phase;
        let p = self.p();
        let width = self.home_module_content_width(HomeModuleId::ContinuityWorkspace);
        let height = self
            .home_modules
            .module_height(HomeModuleId::ContinuityWorkspace);
        let eff_h = self.resolve_effective_height(HomeModuleId::ContinuityWorkspace, height);
        let profile = self.compute_home_module_value_profile(
            HomeModuleId::ContinuityWorkspace,
            width,
            height,
        );
        let task_limit = match eff_h {
            HomeModuleHeight::Compact => 1,
            HomeModuleHeight::Standard | HomeModuleHeight::Auto => 2,
            HomeModuleHeight::Tall => 4,
        };
        let tasks = self.home_recent_tasks_limited(task_limit);
        let total_saved = self
            .workspace
            .journal
            .tasks
            .iter()
            .filter(|t| self.workspace_visible(t))
            .count();

        let heading = Flex::row()
            .with_main_axis_size(MainAxisSize::Max)
            .with_cross_axis_alignment(CrossAxisAlignment::Start)
            .with_spacing(S2)
            .with_child(self.section_icon_badge(UiIcon::Archive, 15., 26.))
            .with_child(
                Expanded::new(
                    1.,
                    self.vstack(
                        2.,
                        vec![
                            self.wrap(vec![
                                self.heading("接着上次做"),
                                if total_saved > 0 {
                                    self.pill_badge(
                                        format!("显示 {} / {total_saved} 条", tasks.len()),
                                        p.text2,
                                        p.card2,
                                    )
                                } else {
                                    Empty::new().finish()
                                },
                            ]),
                            if eff_h == HomeModuleHeight::Compact { Empty::new().finish() } else {
                                self.text("对话草稿、生成文件与手机回传进度", CAPTION, p.text2)
                            },
                        ],
                    ),
                )
                .finish(),
            )
            .finish();
        let header = self.responsive_columns(
            560.,
            S2,
            S1,
            CrossAxisAlignment::Center,
            vec![
                (1., heading),
                (
                    0.22,
                    self.button_icon(
                        "home-continue-amoo",
                        "所有对话",
                        UiIcon::Chat,
                        Action::HomeShowHistory,
                        Btn::Ghost,
                    ),
                ),
            ],
        );
        #[cfg(test)]
        let header = SavePosition::new(header, "continuity-header").finish();
        let mut children = vec![header];
        if tasks.is_empty() {
            let step_card = |index: usize, icon, fg, bg, step: &str, desc: &str| -> El {
                #[cfg(not(test))]
                let _ = index;
                let copy = self.vstack(
                    2.,
                    vec![
                        self.text_w(step, CAPTION, p.text, Weight::Semibold),
                        self.text(desc, MICRO, p.text2),
                    ],
                );
                #[cfg(test)]
                let copy =
                    SavePosition::new(copy, &format!("continuity-empty-copy-{index}")).finish();
                let card = self.card_box(
                    Flex::row()
                        .with_main_axis_size(MainAxisSize::Max)
                        .with_cross_axis_alignment(CrossAxisAlignment::Start)
                        .with_spacing(S2)
                        .with_child(self.icon_badge(icon, 14., fg, bg, 28.))
                        .with_child(Expanded::new(1., copy).finish())
                        .finish(),
                    p.surface,
                    p.border,
                    R_SM,
                    10.,
                    8.,
                );
                #[cfg(test)]
                let card =
                    SavePosition::new(card, &format!("continuity-empty-step-{index}")).finish();
                card
            };
            let mut empty_stack = vec![
                self.text_w("还没有可继续的讨论", SUBHEAD, p.text, Weight::Semibold),
                self.text(
                    "说一件想完成的事。讨论、草稿和生成的文件会留在同一条对话里。",
                    CAPTION,
                    p.text2,
                ),
            ];
            if eff_h != HomeModuleHeight::Compact {
                empty_stack.push(self.responsive_columns(
                    720.,
                    S2,
                    S2,
                    CrossAxisAlignment::Start,
                    vec![
                        (
                            1.,
                            step_card(
                                0,
                                UiIcon::Smartphone,
                                p.accent,
                                p.accent_soft,
                                "1. 跨端随时发起",
                                "手机或电脑输入想法与素材",
                            ),
                        ),
                        (
                            1.,
                            step_card(
                                1,
                                UiIcon::File,
                                p.teal,
                                p.teal_soft,
                                "2. 讨论与成稿",
                                "自动保留草稿并生成结构化文档",
                            ),
                        ),
                        (
                            1.,
                            step_card(
                                2,
                                UiIcon::Check,
                                p.success,
                                p.success_soft,
                                "3. 核验回传手机",
                                "成果一键预览或校验发回手机",
                            ),
                        ),
                    ],
                ));
            }
            let empty = self.card_box(
                self.vstack(S2, empty_stack),
                p.card,
                p.border,
                R_MD,
                12.,
                12.,
            );
            #[cfg(test)]
            let empty = SavePosition::new(empty, "continuity-empty-card").finish();
            children.push(empty);
        }

        let mut task_cards = Vec::new();
        for (index, task) in tasks.iter().take(task_limit).enumerate() {
            let is_phone_origin = task.id.starts_with("phone-work-");
            let phone_awaiting_delivery = is_phone_origin
                && (task.route_note.contains("待回传")
                    || task.note.contains("待回传")
                    || task.outputs.iter().any(|o| o.kind.contains("待回传")));
            let phone_queued = is_phone_origin && task.route_note.contains("排队");
            let (phase, phase_fg, phase_bg, phase_icon, stage_idx) = match task
                .steps
                .last()
                .map(|s| s.phase)
            {
                _ if self
                    .workspace
                    .running
                    .as_ref()
                    .is_some_and(|run| run.task == task.id) =>
                {
                    ("正在处理", p.accent, p.accent_soft, UiIcon::Refresh, 1)
                }
                _ if phone_awaiting_delivery => (
                    "待回传手机",
                    p.warning,
                    p.warning_soft,
                    UiIcon::Smartphone,
                    2,
                ),
                _ if phone_queued => ("排队等待处理", p.accent, p.accent_soft, UiIcon::Clock, 0),
                Some(Phase::Running) => (
                    "上次处理尚未确认",
                    p.warning,
                    p.warning_soft,
                    UiIcon::Clock,
                    1,
                ),
                Some(Phase::Failed) => (
                    "上次未成功，可继续处理",
                    p.danger,
                    p.danger_soft,
                    UiIcon::Alert,
                    1,
                ),
                Some(Phase::Unconfirmed) => {
                    ("结果需要确认", p.warning, p.warning_soft, UiIcon::Alert, 2)
                }
                Some(Phase::Stopped) => ("已暂停，可接着做", p.text2, p.card2, UiIcon::Clock, 1),
                _ if !task.draft.trim().is_empty() => {
                    ("有未发送的想法", p.indigo, p.indigo_soft, UiIcon::Send, 0)
                }
                _ if !task.outputs.is_empty() => (
                    "已有文件可以查看",
                    p.success,
                    p.success_soft,
                    UiIcon::File,
                    2,
                ),
                _ if !task.turns.is_empty() => ("讨论已保留", p.teal, p.teal_soft, UiIcon::Chat, 1),
                _ => ("待继续", p.text2, p.card2, UiIcon::Clock, 0),
            };

            let snippet = if !task.draft.trim().is_empty() {
                task.draft.as_str()
            } else {
                task.turns
                    .iter()
                    .rev()
                    .find(|turn| turn.user)
                    .map(|turn| turn.text.as_str())
                    .unwrap_or("")
            };
            let snippet = snippet.split_whitespace().collect::<Vec<_>>().join(" ");
            let origin = if is_phone_origin {
                "手机发起 · "
            } else {
                ""
            };

            let title = self.line_w(
                Self::truncate_chars(&task.title, profile.char_budget),
                BODY + 1.,
                p.text,
                Weight::Semibold,
            );
            #[cfg(test)]
            let title =
                SavePosition::new(title, &format!("continuity-task-title-{index}")).finish();
            let mut badges = Vec::new();
            if is_phone_origin {
                badges.push(self.pill_badge_icon(
                    "手机发起",
                    UiIcon::Smartphone,
                    p.teal,
                    p.teal_soft,
                ));
            }
            badges.push(self.pill_badge_icon(phase, phase_icon, phase_fg, phase_bg));
            let heading = Flex::row()
                .with_main_axis_size(MainAxisSize::Max)
                .with_cross_axis_alignment(CrossAxisAlignment::Center)
                .with_spacing(S2)
                .with_child(self.icon_badge(
                    if is_phone_origin {
                        UiIcon::Smartphone
                    } else {
                        phase_icon
                    },
                    16.,
                    phase_fg,
                    phase_bg,
                    34.,
                ))
                .with_child(Expanded::new(1., title).finish())
                .finish();
            let mut copy = vec![heading, self.wrap(badges)];
            if eff_h != HomeModuleHeight::Compact
                && !snippet.is_empty()
                && snippet.trim() != task.title.trim()
            {
                copy.push(self.text(
                    Self::truncate_chars(&snippet, profile.char_budget),
                    CAPTION,
                    p.text2,
                ));
            }
            if eff_h == HomeModuleHeight::Tall
                && is_phone_origin
                && !task.note.trim().is_empty()
                && task.note.trim() != snippet.trim()
            {
                copy.push(self.text(
                    Self::truncate_chars(task.note.trim(), profile.char_budget),
                    CAPTION,
                    p.teal,
                ));
            }
            copy.push(self.text(
                format!("{origin}{}", home_updated_label(task.updated)),
                MICRO,
                p.text2,
            ));
            let progress = self.stepper_index(&["讨论", "成稿", "回传"], stage_idx);
            #[cfg(test)]
            let progress =
                SavePosition::new(progress, &format!("continuity-task-progress-{index}")).finish();
            if eff_h != HomeModuleHeight::Compact { copy.push(progress); }
            let content = self.vstack(5., copy);
            let action = self.button_icon(
                format!("home-resume-{}", task.id),
                if !task.draft.trim().is_empty() {
                    "继续写"
                } else {
                    "继续这件事"
                },
                UiIcon::ArrowUpRight,
                Action::HomeResumeTask(task.id.clone()),
                if index == 0 {
                    Btn::Primary
                } else {
                    Btn::Secondary
                },
            );
            #[cfg(test)]
            let action =
                SavePosition::new(action, &format!("continuity-task-action-{index}")).finish();
            // The action owns a separate row; status/stepper wrapping can never
            // paint under it, even when a saved wide module is squeezed narrow.
            let card = self.card_box(
                self.vstack(S2, vec![content, self.wrap(vec![action])]),
                p.card,
                if index == 0 {
                    with_alpha_f(p.accent, 0.32)
                } else {
                    p.border
                },
                R_MD,
                12.,
                if eff_h == HomeModuleHeight::Compact {
                    8.
                } else {
                    12.
                },
            );
            #[cfg(test)]
            let card = SavePosition::new(card, &format!("continuity-task-card-{index}")).finish();
            task_cards.push(card);
        }

        let output_limit = match eff_h {
            HomeModuleHeight::Compact => 1,
            HomeModuleHeight::Standard | HomeModuleHeight::Auto => 2,
            HomeModuleHeight::Tall => 4,
        };
        let output_card = |index: usize,
                           name: &str,
                           badge: El,
                           detail: String,
                           fg: ColorU,
                           bg: ColorU,
                           action: El|
         -> El {
            #[cfg(not(test))]
            let _ = index;
            let title = self.line_w(
                Self::truncate_chars(name, profile.char_budget),
                BODY,
                p.text,
                Weight::Semibold,
            );
            #[cfg(test)]
            let title =
                SavePosition::new(title, &format!("continuity-output-title-{index}")).finish();
            let body = Flex::row()
                .with_main_axis_size(MainAxisSize::Max)
                .with_cross_axis_alignment(CrossAxisAlignment::Start)
                .with_spacing(S2)
                .with_child(self.icon_badge(UiIcon::File, 15., fg, bg, 30.))
                .with_child(
                    Expanded::new(
                        1.,
                        self.vstack(
                            3.,
                            vec![
                                title,
                                self.wrap(vec![badge]),
                                self.text(detail, MICRO, p.text2),
                            ],
                        ),
                    )
                    .finish(),
                )
                .finish();
            #[cfg(test)]
            let action =
                SavePosition::new(action, &format!("continuity-output-action-{index}")).finish();
            let card = self.card_box(
                self.vstack(S2, vec![body, self.wrap(vec![action])]),
                p.card,
                p.border,
                R_SM,
                12.,
                10.,
            );
            #[cfg(test)]
            let card = SavePosition::new(card, &format!("continuity-output-card-{index}")).finish();
            card
        };
        let mut outputs = Vec::new();
        let mut seen = std::collections::HashSet::new();
        let mut output_tasks: Vec<_> = self
            .workspace
            .journal
            .tasks
            .iter()
            .filter(|task| self.workspace_visible(task) && !task.outputs.is_empty())
            .collect();
        output_tasks.sort_by_key(|task| std::cmp::Reverse(task.updated));
        for task in output_tasks {
            if seen.len() >= output_limit {
                break;
            }
            for index in task.current_output_indices().into_iter().rev() {
                let output = &task.outputs[index];
                if seen.len() >= output_limit || !seen.insert(output.path.clone()) {
                    continue;
                }
                let delivered = output.kind.contains("已回传")
                    || task.receipts.iter().any(|receipt| {
                        receipt.path == output.path
                            && receipt.success
                            && task.device.as_deref() == Some(receipt.device.as_str())
                            && task.account == receipt.account
                    });
                let fg = if delivered { p.success } else { p.accent };
                let bg = if delivered {
                    p.success_soft
                } else {
                    p.accent_soft
                };
                outputs.push(output_card(
                    outputs.len(),
                    &output.name,
                    self.pill_badge_icon(
                        if delivered {
                            "已达手机"
                        } else {
                            "本地归档"
                        },
                        if delivered {
                            UiIcon::Check
                        } else {
                            UiIcon::FolderOpen
                        },
                        fg,
                        bg,
                    ),
                    format!(
                        "{} · {}",
                        if delivered {
                            "曾发送到手机"
                        } else {
                            "保存在电脑"
                        },
                        home_updated_label(task.updated)
                    ),
                    fg,
                    bg,
                    self.button_icon(
                        format!("home-output-{}-{}", task.id, seen.len()),
                        "打开成果",
                        UiIcon::FolderOpen,
                        Action::HomeOpenTaskOutput {
                            task: task.id.clone(),
                            path: output.path.clone(),
                        },
                        Btn::Secondary,
                    ),
                ));
            }
            if seen.len() >= output_limit {
                break;
            }
        }
        for (index, output) in self.work.artifacts.iter().enumerate() {
            if seen.len() >= output_limit {
                break;
            }
            if !seen.insert(output.path.clone()) {
                continue;
            }
            outputs.push(output_card(
                outputs.len(),
                &output.name,
                self.pill_badge("工作台产物", p.accent, p.accent_soft),
                "保存在电脑".into(),
                p.accent,
                p.accent_soft,
                self.button_icon(
                    format!("home-artifact-{index}"),
                    "打开成果",
                    UiIcon::FolderOpen,
                    Action::Work(WorkAction::PreviewArtifact(index)),
                    Btn::Secondary,
                ),
            ));
        }

        let side_by_side = matches!(width, HomeModuleWidth::TwoThirds | HomeModuleWidth::Full)
            || (width == HomeModuleWidth::OneHalf && eff_h == HomeModuleHeight::Tall);
        if side_by_side && !task_cards.is_empty() && !outputs.is_empty() {
            let mut out_col = vec![self.hstack(
                S2,
                vec![
                    self.section_icon_badge(UiIcon::FolderOpen, 14., 24.),
                    self.text_w("已有文件", BODY, p.text, Weight::Semibold),
                    self.pill_badge(format!("{} 份成果", outputs.len()), p.teal, p.teal_soft),
                ],
            )];
            out_col.extend(outputs);
            children.push(self.responsive_columns(
                620.,
                S2,
                S2,
                CrossAxisAlignment::Start,
                vec![
                    (1.15, self.vstack(S2, task_cards)),
                    (1.0, self.vstack(S2, out_col)),
                ],
            ));
        } else {
            if !task_cards.is_empty() {
                if profile.columns >= 2 && task_cards.len() >= 2 {
                    children.push(self.responsive_columns(
                        360. * task_cards.len() as f32,
                        S2,
                        S2,
                        CrossAxisAlignment::Start,
                        task_cards.into_iter().map(|card| (1., card)).collect(),
                    ));
                } else {
                    children.extend(task_cards);
                }
            }
            if !outputs.is_empty() {
                children.push(self.divider());
                children.push(self.hstack(
                    S2,
                    vec![
                        self.section_icon_badge(UiIcon::FolderOpen, 14., 24.),
                        self.text_w("已有文件", BODY, p.text, Weight::Semibold),
                        self.pill_badge(format!("{} 份成果", outputs.len()), p.teal, p.teal_soft),
                    ],
                ));
                children.extend(outputs);
            }
        }
        if self.work.running
            || self.work.error.is_some()
            || !self.fields[F_WORK_PROMPT].text.trim().is_empty()
            || !self.work.attachments.is_empty()
        {
            children.push(self.button_icon(
                "home-continue-work",
                if self.work.running {
                    "查看文件处理进度"
                } else {
                    "继续文件任务"
                },
                UiIcon::File,
                Action::Page(Page::Work),
                Btn::Secondary,
            ));
        }
        let notice = |text: &str, fg, bg, border, action: El| {
            self.card_box(
                self.vstack(
                    S2,
                    vec![self.text(text, CAPTION, fg), self.wrap(vec![action])],
                ),
                bg,
                border,
                R_SM,
                10.,
                8.,
            )
        };
        if !self.demo_mode && self.selected.is_none() {
            children.push(notice(
                "手机暂未连接，仍可继续电脑里的讨论和草稿。",
                p.text2,
                p.card2,
                p.border,
                self.button_icon(
                    "home-connect",
                    "连接手机",
                    UiIcon::Link,
                    Action::Page(Page::Connect),
                    Btn::Secondary,
                ),
            ));
        } else if self.back_screen.stepos_suite_error.is_some() || self.push.error.is_some() {
            children.push(notice(
                "手机有部分内容未同步，当前显示已保存的记录。",
                p.warning,
                p.warning_soft,
                with_alpha_f(p.warning, 0.3),
                self.button_icon(
                    "home-sync-retry",
                    "重试同步",
                    UiIcon::Refresh,
                    Action::HomeRefreshAll,
                    Btn::Secondary,
                ),
            ));
        }
        let panel = self.home_frame(HomeModuleId::ContinuityWorkspace, children);
        #[cfg(test)]
        let panel = SavePosition::new(panel, "continuity-panel").finish();
        panel
    }
}

#[cfg(test)]
mod continuity_layout_tests {
    use super::*;
    use stepx_companion::amoo_workspace::{Executor, Output, Phase, Step, Task};

    struct ContinuityOnly(Companion);
    impl facloud_ui::Entity for ContinuityOnly {
        type Event = ();
    }
    impl facloud_ui::View for ContinuityOnly {
        fn ui_name() -> &'static str {
            "home_continuity_geometry"
        }
        fn render(&self, _: &facloud_ui::AppContext) -> El {
            // SavePosition records within the stack namespace supplied by the
            // production host; use that same host in the isolated layout test.
            Stack::new()
                .with_child(Align::new(self.0.render_home_continuity()).top_left().finish())
                .finish()
        }
    }
    impl facloud_ui::TypedActionView for ContinuityOnly {
        type Action = ();
    }

    fn inside(child: RectF, parent: RectF, name: &str) {
        assert!(
            child.origin().x() >= parent.origin().x() - 1.
                && child.max_x() <= parent.max_x() + 1.
                && child.origin().y() >= parent.origin().y() - 1.
                && child.max_y() <= parent.max_y() + 1.,
            "{name}: {child:?} outside {parent:?}"
        );
    }

    #[test]
    fn home_continuity_real_layout_keeps_progress_titles_and_actions_inside_narrow_cards() {
        facloud_ui::App::test((), |mut app| async move {
            for height in [
                HomeModuleHeight::Compact,
                HomeModuleHeight::Standard,
                HomeModuleHeight::Tall,
            ] {
                for width in [260., 390., 720., 820., 1100.] {
                    for scenario in 0..3 {
                        let with_outputs = scenario == 2;
                        let mut companion = Companion::new_for_test();
                        companion.demo_mode = false;
                        companion.home_modules.set_module_size(
                            HomeModuleId::ContinuityWorkspace,
                            HomeModuleWidth::TwoThirds,
                            height,
                        );
                        companion.work.artifacts.clear();
                        companion.workspace.journal.tasks = (0..2)
                            .map(|i| {
                                let mut task = Task::new(None, None);
                                task.id = format!("phone-work-layout-{i}");
                                task.title = "跨端办公评审任务VeryLongUnbrokenTitle".repeat(8);
                                task.draft = "保留的评审草稿需要继续整理".repeat(10);
                                task.updated -= i;
                                task.steps.push(Step {
                                    executor: Executor::Phone,
                                    phase: Phase::Failed,
                                    note: "上次未成功".into(),
                                });
                                if with_outputs {
                                    task.outputs.push(Output {
                                        path: PathBuf::from(format!(
                                            "/tmp/stepx-continuity-layout-{i}.docx"
                                        )),
                                        name: format!(
                                            "{}.docx",
                                            "桌面伴侣日常办公使用方案LongFilename".repeat(8)
                                        ),
                                        kind: "文档".into(),
                                        lab_id: None,
                                    });
                                }
                                task
                            })
                            .collect();
                        if scenario == 0 {
                            companion.workspace.journal.tasks.clear();
                        }
                        let (window, _) = app
                            .add_window(facloud_ui::platform::WindowStyle::NotStealFocus, |_| {
                                ContinuityOnly(companion)
                            });
                        let root = app.root_view_id(window).unwrap();
                        app.update(move |ctx| {
                            let mut presenter = facloud_ui::Presenter::new(window);
                            presenter.invalidate(facloud_ui::WindowInvalidation {
                                updated: std::collections::HashSet::from([root]), ..Default::default()
                            }, ctx);
                            presenter.build_scene(vec2f(width, 5000.), 1., None, ctx);
                            let positions = presenter.position_cache();
                            let rect = |id: &str| positions.get_position(id).unwrap_or_else(|| panic!("missing {id}"));
                            let panel = rect("continuity-panel");
                            assert!(panel.max_x() <= width + 1., "panel exceeds actual width {width}: {panel:?}");
                            inside(rect("continuity-header"), panel, "header");
                            if scenario == 0 {
                                let empty = rect("continuity-empty-card");
                                inside(empty, panel, "empty state");
                                if height != HomeModuleHeight::Compact {
                                    for i in 0..3 {
                                        let step = rect(&format!("continuity-empty-step-{i}"));
                                        inside(step, empty, "empty step");
                                        inside(rect(&format!("continuity-empty-copy-{i}")), step, "empty step copy");
                                    }
                                }
                            }
                            let count = if scenario == 0 { 0 } else if height == HomeModuleHeight::Compact { 1 } else { 2 };
                            for i in 0..count {
                                let card = rect(&format!("continuity-task-card-{i}"));
                                let title = rect(&format!("continuity-task-title-{i}"));
                                let action = rect(&format!("continuity-task-action-{i}"));
                                inside(card, panel, "task"); inside(title, card, "task title");
                                inside(action, card, "resume action");
                                if height == HomeModuleHeight::Compact {
                                    assert!(positions.get_position(&format!("continuity-task-progress-{i}")).is_none());
                                } else {
                                    let progress = rect(&format!("continuity-task-progress-{i}"));
                                    inside(progress, card, "task progress");
                                    assert!(progress.max_y() <= action.origin().y(), "progress overlaps resume: {progress:?}/{action:?}");
                                }
                                if with_outputs {
                                    let output = rect(&format!("continuity-output-card-{i}"));
                                    let output_title = rect(&format!("continuity-output-title-{i}"));
                                    let open = rect(&format!("continuity-output-action-{i}"));
                                    inside(output, panel, "output"); inside(output_title, output, "output title"); inside(open, output, "open action");
                                    assert!(output_title.max_y() <= open.origin().y(), "output title overlaps open action");
                                    assert!(card.max_x() <= output.origin().x() || output.max_x() <= card.origin().x()
                                        || card.max_y() <= output.origin().y() || output.max_y() <= card.origin().y(),
                                        "task/output columns overlap at width {width}: {card:?}/{output:?}");
                                }
                            }
                        });
                    }
                }
            }
        });
    }
}
